    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 5,
    unitPrice: 8500,
    vatRate: 21,
    discountPercent: 2.5,
  });
  assert.deepEqual(result.value.lines[1], {
    sku: 'LOGO-PACK',
    name: 'Logo package',
