      { sku: 'DEV-HOUR', qty: 10 }, // 10 * 9500 = 95000, discount 4750, after-discount 90250, VAT 18953 (21%)
      { sku: 'COPY-HOUR', qty: 3 }, // 3 * 6000 = 18000, discount 900, after-discount 17100, VAT 3591 (21%)
