test('invoiceTotals: happy path with single line', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // 10 * 9500 = 95000, discount 5%, VAT 21%
  });

  const totals = invoiceTotals(result.value);

  // Subtotal: 95000
  // Discount: 4750 (5% of 95000)
  // Amount after discount: 90250
  // VAT: 18952.5 → 18953 (21% of 90250, rounded)
  // Total: 90250 + 18953 = 109203

  assert.deepEqual(totals, {
    ok: true,
    value: { subtotal: 95000, discount: 4750, vat: 18953, total: 109203 },
  });
});

test('invoiceTotals: happy path with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // 5 * 8500 = 42500, discount 2125, after-discount 40375, VAT 8479 (21%)
      { sku: 'DEV-HOUR', qty: 10 }, // 10 * 9500 = 95000, discount 4750, after-discount 90250, VAT 18953 (21%)
      { sku: 'COPY-HOUR', qty: 3 }, // 3 * 6000 = 18000, discount 900, after-discount 17100, VAT 3591 (21%)
    ],
  });

  const totals = invoiceTotals(result.value);

  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 155500);
  assert.equal(totals.value.discount, 7775);
  assert.equal(totals.value.vat, 31023); // 8479 + 18953 + 3591
  assert.equal(totals.value.total, 178748); // 155500 - 7775 + 31023
});

