  assert.equal(totals.value.subtotal, 155500);
  assert.equal(totals.value.discount, 7775);
  assert.equal(totals.value.vat, 31023); // 8479 + 18953 + 3591
  assert.equal(totals.value.total, 178748); // 155500 - 7775 + 31023
});

