    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  const result = removeLine(invoiceResult.value, 'DES-HOUR');

  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-10-15');
  assert.equal(result.value.status, 'draft');
});

test('addLine then removeLine workflow', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const afterAdd = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(afterAdd.ok, true);
  assert.equal(afterAdd.value.lines.length, 2);

  const afterRemove = removeLine(afterAdd.value, 'DES-HOUR');
  assert.equal(afterRemove.ok, true);
  assert.equal(afterRemove.value.lines.length, 1);
  assert.equal(afterRemove.value.lines[0].sku, 'DEV-HOUR');
});

test('addLine with same SKU multiple times', () => {
