  assert.equal(afterFirst.value.lines[0].qty, 8); // 5 + 3

  const afterSecond = addLine(afterFirst.value, { sku: 'DEV-HOUR', qty: 2 });
  assert.equal(afterSecond.value.lines[0].qty, 10); // 8 + 2
  assert.equal(afterSecond.value.lines.length, 1);
});

