test('invoiceTotals: large invoice with many lines', () => {
  const lines = [];
  for (let i = 0; i < 10; i++) {
    lines.push({ sku: 'DEV-HOUR', qty: 5 });
  }

  const result = createInvoice({
    customerId: 'C-002', // Standard tier (0%)
    issueDate: '2024-10-15',
    lines,
  });

  const totals = invoiceTotals(result.value);

  // Subtotal: 10 * (5 * 9500) = 475000
  // Discount: 0
  // VAT: 21% of 475000 = 99750
  // Total: 475000 + 99750 = 574750

  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 475000);
  assert.equal(totals.value.discount, 0);
  assert.equal(totals.value.vat, 99750);
  assert.equal(totals.value.total, 574750);
});

